<?php require_once __DIR__.'/config/database.php';$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama']);$username=trim($_POST['username']);$p=$_POST['password'];$k=$_POST['konfirmasi'];if($nama===''||$username===''||$p==='')$error='Semua field wajib diisi.';elseif(strlen($username)<4)$error='Username minimal 4 karakter.';elseif(strlen($p)<6)$error='Password minimal 6 karakter.';elseif($p!==$k)$error='Konfirmasi password tidak sama.';else{$s=$pdo->prepare("SELECT id FROM users WHERE username=?");$s->execute([$username]);if($s->fetch())$error='Username sudah digunakan.';else{$pdo->prepare("INSERT INTO users(nama,username,password) VALUES(?,?,?)")->execute([$nama,$username,password_hash($p,PASSWORD_DEFAULT)]);$success='Registrasi berhasil, silakan login.';}}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrasi</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#12372a}.box{max-width:460px;margin:7vh auto}</style></head><body><div class="box card p-4 shadow"><h3 class="text-center">💰 Apotek Cashflow</h3><p class="text-center text-muted">Registrasi akun</p><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><form method="post"><input name="nama" class="form-control mb-3" placeholder="Nama lengkap" required><input name="username" class="form-control mb-3" placeholder="Username" minlength="4" required><input type="password" name="password" class="form-control mb-3" placeholder="Password" minlength="6" required><input type="password" name="konfirmasi" class="form-control mb-3" placeholder="Konfirmasi password" required><button class="btn btn-success w-100">Daftar</button></form><div class="text-center mt-3"><a href="login.php">Kembali ke login</a></div></div></body></html>